import{z as n,x as s,o as l,c as m,q as B,j as o,D as e,d as a,s as A,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"KV 成本模型","description":"","frontmatter":{"title":"KV 成本模型","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-cost-model.md","filePath":"llm/kv-cost-model.md","lastUpdated":1791063341000}'),d={name:"llm/kv-cost-model.md"};function p(c,E,f,_,C,D){const r=s("Mermaid");return l(),m("div",null,[E[2]||(E[2]=B('<h1 id="kv-成本模型" tabindex="-1">KV 成本模型 <a class="header-anchor" href="#kv-成本模型" aria-label="Permalink to &quot;KV 成本模型&quot;">​</a></h1><div class="epigraph"><p>每一份 KV 都在付四笔账：占地的租金、每步扫描的电费、搬运的网费、丢了重算的工费；成本模型就是把它们乘出来。</p><footer>—— 据 Pope et al., 2022 的成本会计口径与开放 API 缓存折扣定价实践整理</footer></div><p><a href="/llm/kv-measurement-pitfalls">上一课</a>让数字可信，本课让数字可钱。前面每一课的决策——精度、配额、驱逐、合并、offload、迁移——最终都要回答「值不值」，而值不值的分子分母就是这四笔账。字节表在<a href="/llm/kv-longcontext-budget">预算课</a>已经编好，本课把字节乘上单价与时间，得到服务一份上下文的真实成本，并推出整个课程最划算的一条决策规则：存还是重算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KV 成本有四条腿。<strong>容量</strong>：HBM 是稀缺资本，一份常驻 KV 按字节 × 时间交租金，长会话把页 pin 越久账越厚。<strong>带宽与能耗</strong>：decode 每步扫全部可见 KV，TPOT 与能耗都近似正比于每步字节——这份账随长度线性，在 128K 处从零头变主项。<strong>传输</strong>：<a href="/llm/pd-kv-transfer">PD 分离</a>的交接、<a href="/llm/kv-distributed-migration">迁移</a>的搬移、跨域拉取，都按 GB 计网费。<strong>重算</strong>：缓存未命中、被逐出的历史在多轮里杀回、迁移失败兜底，都要重付一次 prefill 的算力费。四条腿的价目不同质——一个按字节·秒，一个按字节·步，一个按字节·次，一个按 token·次——混在一个「GPU 成本」里就无从优化。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把成本写成请求生命周期的积分。单请求成本</p> \\[C = c_{\\rm w} + \\int_0^T \\big( c_{\\rm mem} \\cdot V(t) \\big)\\,dt + c_{\\rm bw} \\sum_{s} \\big( V(t_s) \\big) + c_{\\rm net} \\cdot M + c_{\\rm prefill} \\cdot R, \\]<p>其中 \\(V(t)\\) 是<a href="/llm/kv-longcontext-budget">有效字节表</a>给出的 \\(t\\) 时刻 KV 体积（已乘量化、驱逐、合并的折扣），\\(M\\) 是搬运字节量，\\(R\\) 是重算次数。前缀<a href="/llm/kv-prefix-cache">共享</a>把 \\(V\\) 的提示段按引用数摊薄。这个式子的用途不是精确到分，而是回答三个决策：这份 KV 值得留多久、哪一刀压缩最划算、迁移是否回本。</p><p>核心规则是<strong>存与重算的盈亏平衡</strong>。一份 KV 持有的租金随时间线性涨，重算一次的工费按次付，于是有临界时长</p> \\[T^{*} = \\frac{c_{\\rm prefill}(n)}{c_{\\rm mem}\\cdot V}\\,, \\]<p>命中间隔短于 \\(T^*\\) 的会话，缓存省钱；长于 \\(T^*\\) 的，删掉重算更便宜。<a href="/llm/kv-tiered-storage">分层存储</a>「冷到哪一层」就是这条除法的工程版：介质越慢租金越低，\\(T^*\\) 越长。</p><p><span class="marginnote">数字实例：设一份前缀 KV 每小时的容量租金折合 0.1 元（\\(c_{\\rm mem} V\\)），重算一次要 2 元（\\(c_{\\rm prefill}\\)），则 \\(T^* = 2 / 0.1 = 20\\) 小时——会话 20 小时内还会回来就值得存着，超过就删掉、下次重算更便宜。</span></p>',13)),(l(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E6%9C%89%E6%95%88%E5%AD%97%E8%8A%82%E8%A1%A8%20V(t)%22%5D%20--%3E%20MEM%5B%22%E5%AE%B9%E9%87%8F%EF%BC%9AV%20%C3%97%20%E6%97%B6%E9%97%B4%20%C3%97%20%E5%86%85%E5%AD%98%E5%8D%95%E4%BB%B7%22%5D%0A%20%20V%20--%3E%20BW%5B%22%E5%B8%A6%E5%AE%BD%EF%BC%9A%E6%AF%8F%E6%AD%A5%20V%20%C3%97%20%E7%94%B5%E4%BB%B7%22%5D%0A%20%20V%20--%3E%20NET%5B%22%E4%BC%A0%E8%BE%93%EF%BC%9A%E6%90%AC%E8%BF%90%E5%AD%97%E8%8A%82%20%C3%97%20%E7%BD%91%E4%BB%B7%22%5D%0A%20%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%20%2F%20%E9%80%90%E5%87%BA%20%2F%20%E8%BF%81%E7%A7%BB%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20RE%5B%22%E9%87%8D%E7%AE%97%EF%BC%9Aprefill%20%E5%B7%A5%E8%B4%B9%22%5D%0A%20%20MEM%20--%3E%20STAR%7B%22%E5%91%BD%E4%B8%AD%E9%97%B4%E9%9A%94%20vs%20T*%22%7D%0A%20%20RE%20--%3E%20STAR%0A%20%20STAR%20--%3E%7C%22%E7%9F%AD%E4%BA%8E%20T*%22%7C%20KEEP%5B%22%E7%95%99%E7%BC%93%E5%AD%98%EF%BC%9Aoffload%20%2F%20%E5%88%86%E5%B1%82%22%5D%0A%20%20STAR%20--%3E%7C%22%E9%95%BF%E4%BA%8E%20T*%22%7C%20DROP%5B%22%E5%88%A0%E6%8E%89%EF%BC%9A%E9%87%8D%E7%AE%97%E6%9B%B4%E4%BE%BF%E5%AE%9C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("为什么长上下文的成本被 KV 主导：权重的账按请求秒摊是常数，KV 的账按字节×时间积分随长度与驻留时长线性涨——上下文一长，常数被积分吞掉。这也解释了"),t("a",{href:"/llm/prompt-cache-billing"},"开放 API 的定价结构"),a("：缓存命中的输入给出大幅折扣、另收小额存储费——供应商侧重算一份长前缀的电费比替你存着更贵，折扣就是把节省让渡给把前缀写得可缓存的调用方。压缩四刀在成本模型里各占一格：量化直接砍 \\(c_{\\rm mem}\\) 与 \\(c_{\\rm bw}\\) 的系数，驱逐与合并缩短 \\(V(t)\\) 的积分上限，offload 把 \\(c_{\\rm mem}\\) 换成便宜的介质加一笔 \\(c_{\\rm net}\\)——同一张表上的不同列，优化顺序按边际收益排。")],-1)),(l(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BILL%5B%22%E6%88%90%E6%9C%AC%E8%A1%A8%E7%9A%84%E5%9B%9B%E5%88%97%22%5D%20--%3E%20Q%5B%22%E9%87%8F%E5%8C%96%EF%BC%9A%E7%A0%8D%20c_mem%20%E4%B8%8E%20c_bw%20%E7%9A%84%E7%B3%BB%E6%95%B0%22%5D%0A%20%20BILL%20--%3E%20E%5B%22%E9%A9%B1%E9%80%90%20%2F%20%E5%90%88%E5%B9%B6%EF%BC%9A%E7%BC%A9%E7%9F%AD%20V(t)%20%E7%9A%84%E7%A7%AF%E5%88%86%E4%B8%8A%E9%99%90%22%5D%0A%20%20BILL%20--%3E%20O%5B%22offload%EF%BC%9A%E6%8D%A2%E6%88%90%E4%BE%BF%E5%AE%9C%E4%BB%8B%E8%B4%A8%EF%BC%8C%E5%A4%9A%E4%BB%98%E4%B8%80%E7%AC%94%20c_net%22%5D%0A%20%20BILL%20--%3E%20P%5B%22%E5%89%8D%E7%BC%80%E5%85%B1%E4%BA%AB%EF%BC%9A%E5%AE%B9%E9%87%8F%E8%B4%A6%E6%8C%89%E5%BC%95%E7%94%A8%E6%95%B0%E6%91%8A%E8%96%84%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">直觉类比：四笔账像养一辆车——容量是停车费（按面积乘时长），带宽是每公里油费，传输是按次的过路费，重算是把扔掉的路书重新画一遍的人工费。只盯着油费省，停车费可能在车场里默默滚成大头。</span></p><p><span class="marginnote">代入量级：8B 模型一条 128K 请求的 KV 是 16 GiB（预算课口径）。同一份前缀若有 10 条请求共享，容量账除以 10，而重算账要付 10 次——共享倍数越高，「存」相对「算」的优势越大，前缀工程本质上是在买断重算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本模型不优化质量：把驱逐配额压到 \\(T^*\\) 之内的「省钱」可能换来任务掉点与返工，质量损失要折价入表才有意义。折扣定价是商业口径，与自建集群的单价不同质，跨口径比较要换算成同一单位（每百万 token 或每小时）。多租户下共享前缀的租金要按引用摊，账记在发起者头上会低估共享价值。合规域的驻留有额外成本项，模型里是一个加法项，治理上是红线。最后，\\(T^*\\) 随硬件代际漂移：内存降价、算力涨价都会移动临界点，成本模型的参数要随报价重估。</p><p><span class="marginnote">常见误区：把「缓存命中打一折」理解成存储近乎免费。折扣价其实是供应商把「省下的重算电费」让给你——他们的前提是重算比存贵。自建集群时这笔账要自己列：内存单价、电价、命中率都是你的数，API 的折扣倍数不能照搬。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四笔账不同质：容量按字节·秒、带宽按字节·步、传输按字节·次、重算按 token·次；混报就无法优化。</li><li>单请求成本 = 权重摊销 + 容量积分 + 带宽和 + 传输 + 重算，输入是预算课的有效字节表。</li><li>存与重算的临界时长 \\(T^* = c_{\\rm prefill} / (c_{\\rm mem} V)\\)；分层存储是它的工程版。</li><li>前缀共享摊薄容量账而不摊薄重算账——共享倍数放大「存」的优势。</li><li>成本模型必须配质量折价与代际重估，否则会优化出便宜但不可用的系统。</li><li>出处：Pope et al., 2022；定价结构口径据本仓库提示缓存计费课；不发明文献。</li></ul>',7))])}const T=n(d,[["render",p]]);export{h as __pageData,T as default};
